def ledger(ops: list[str]) -> tuple[dict[str, int], list[int]]:
    accounts = {}  # name -> (balance, frozen)
    history = []
    rejected = []

    arities = {
        "open": 3,
        "deposit": 3,
        "withdraw": 3,
        "transfer": 4,
        "freeze": 2,
        "unfreeze": 2,
        "undo": 1,
    }

    def parse_amount(token):
        if not token or any(c < "0" or c > "9" for c in token):
            return None

        # Small chunks avoid Python's limit on decimal string conversions.
        token = token.lstrip("0")
        value = 0
        for start in range(0, len(token), 9):
            chunk = token[start:start + 9]
            value = value * (10 ** len(chunk)) + int(chunk)
        return value

    for index, operation in enumerate(ops):
        tokens = operation.split(" ")
        verb = tokens[0]

        if verb not in arities or len(tokens) != arities[verb]:
            rejected.append(index)
            continue

        if verb == "undo":
            if not history:
                rejected.append(index)
                continue

            for name, previous in history.pop():
                if previous is None:
                    del accounts[name]
                else:
                    accounts[name] = previous
            continue

        if verb in ("open", "deposit", "withdraw", "transfer"):
            amount = parse_amount(tokens[-1])
            if amount is None or (verb != "open" and amount == 0):
                rejected.append(index)
                continue

        name = tokens[1]
        previous = accounts.get(name)

        if verb == "open":
            if previous is not None:
                rejected.append(index)
                continue
            changes = [(name, (amount, False))]

        else:
            if previous is None:
                rejected.append(index)
                continue

            balance, frozen = previous

            if verb == "deposit":
                changes = [(name, (balance + amount, frozen))]

            elif verb == "withdraw":
                if frozen or balance < amount:
                    rejected.append(index)
                    continue
                changes = [(name, (balance - amount, frozen))]

            elif verb == "transfer":
                destination = tokens[2]
                target = accounts.get(destination)
                if (
                    name == destination
                    or target is None
                    or frozen
                    or balance < amount
                ):
                    rejected.append(index)
                    continue

                target_balance, target_frozen = target
                changes = [
                    (name, (balance - amount, frozen)),
                    (destination, (target_balance + amount, target_frozen)),
                ]

            elif verb == "freeze":
                if frozen:
                    rejected.append(index)
                    continue
                changes = [(name, (balance, True))]

            else:  # unfreeze
                if not frozen:
                    rejected.append(index)
                    continue
                changes = [(name, (balance, False))]

        history.append([(name, accounts.get(name)) for name, _ in changes])
        for name, state in changes:
            accounts[name] = state

    balances = {name: state[0] for name, state in accounts.items()}
    return balances, rejected
